  "code": "def select_words(s, n):
    """This function is designed to filter words from a string based on the count of consonants in each word. It takes a string s and a natural number n, then returns a list of words from s that contain exactly n consonants, in the order they appear in s. If s is an empty string, the function returns an empty list. The function operates under the assumption that the input string contains only letters and spaces.
    Examples:
    select_words("Mary had a little lamb", 4) ==> ["little"]
    select_words("Mary had a little lamb", 3) ==> ["Mary", "lamb"]
    select_words("simple white space", 2) ==> []
    select_words("Hello world", 4) ==> ["world"]
    select_words("Uncle sam", 3) ==> ["Uncle"]
    """
    if not s:
        return []

    vowels = set('aeiouAEIOU')
    selected_words = []

    for word in s.split():
        consonant_count = 0
        for char in word:
            if char.isalpha() and char not in vowels:
                consonant_count += 1
        if consonant_count == n:
            selected_words.append(word)

    return selected_words",
